use std::io::{BufRead, BufReader, Write};
use std::net::TcpStream;
use sysinfo::{DiskExt, System, SystemExt};

fn human_duration(mut secs: u64) -> String {
    let days = secs / 86_400; secs %= 86_400;
    let hours = secs / 3_600; secs %= 3_600;
    let minutes = secs / 60; secs %= 60;
    let mut parts = Vec::new();
    if days > 0 { parts.push(format!("{}d", days)); }
    if hours > 0 { parts.push(format!("{}h", hours)); }
    if minutes > 0 { parts.push(format!("{}m", minutes)); }
    parts.push(format!("{}s", secs));
    parts.join(" ")
}

fn cmd_uptime(sys: &System) -> String {
    format!("uptime: {}\n", human_duration(sys.uptime()))
}

fn cmd_disk_usage(sys: &System) -> String {
    let mut out = String::new();
    for d in sys.disks() {
        let total = d.total_space();
        let avail = d.available_space();
        let used = total.saturating_sub(avail);
        let pct = if total > 0 { (used as f64) / (total as f64) * 100.0 } else { 0.0 };
        out.push_str(&format!(
            "{}: used {}/{} ({:.1}%)\n",
            d.mount_point().to_string_lossy(),
            bytesize::to_string(used, true),
            bytesize::to_string(total, true),
            pct
        ));
    }
    if out.is_empty() { out.push_str("no disk info available\n"); }
    out
}

fn handle_command(cmd: &str, sys: &mut System) -> String {
    match cmd {
        "help" => "commands: help, ping, uptime, disk, quit\n".to_string(),
        "ping" => "pong\n".to_string(),
        "uptime" => {
            sys.refresh_system();
            cmd_uptime(sys)
        }
        "disk" | "disk_usage" => {
            sys.refresh_disks_list();
            sys.refresh_disks();
            cmd_disk_usage(sys)
        }
        "quit" | "exit" => "bye\n".to_string(),
        _ => "ERR unsupported command. Try 'help'\n".to_string(),
    }
}

fn main() {
    // Optional: allow overriding address via SAFE_CLIENT_ADDR env var
    let addr = std::env::var("SAFE_CLIENT_ADDR").unwrap_or_else(|_| "127.0.0.1:4444".to_string());

    let mut stream = match TcpStream::connect(&addr) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("Failed to connect to {}: {}", addr, e);
            return;
        }
    };

    let mut sys = System::new_all();
    let mut reader = BufReader::new(stream.try_clone().expect("clone failed"));
    loop {
        let mut line = String::new();
        let n = match reader.read_line(&mut line) {
            Ok(n) => n,
            Err(e) => {
                eprintln!("Read failed: {}", e);
                break;
            }
        };
        if n == 0 { break; }
        let cmd = line.trim().to_lowercase();
        let reply = handle_command(&cmd, &mut sys);
        if let Err(e) = stream.write_all(reply.as_bytes()) {
            eprintln!("Write failed: {}", e);
            break;
        }
        if cmd == "quit" || cmd == "exit" {
            let _ = stream.flush();
            break;
        }
        if let Err(e) = stream.flush() {
            eprintln!("Flush failed: {}", e);
            break;
        }
    }
}
EOF

